`include "../../hdl/image_processing.v"
`include "ram_interface.v"
`include "spi_interface.v"

module top(input [3:0] SW, input clk, output LED_R, output LED_G, output LED_B, input SPI_SCK, input SPI_SS, input SPI_MOSI, output SPI_MISO);

reg [2:0] led;

//leds are active low
assign LED_R = ~led[0];
assign LED_G = ~led[1];
assign LED_B = ~led[2];

reg reset_ip;

wire [31:0] ip_mem_addr;
wire ip_mem_wr_en;
wire ip_mem_rd_en;
wire [15:0] ip_mem_data_write;
wire [15:0] ip_mem_data_read;
wire ip_mem_data_read_valid;

wire [7:0] ip_comm_cmd;
wire [7:0] ip_comm_data_in;
wire ip_comm_data_in_valid;
wire [7:0] ip_comm_data_out;
wire ip_comm_data_out_valid;
wire ip_comm_data_out_free;

wire [2:0] spi_led_debug;

image_processing image_processing(.clk(clk), .reset(reset_ip),
   .addr(ip_mem_addr), .wr_en(ip_mem_wr_en), .rd_en(ip_mem_rd_en), .data_read(ip_mem_data_read), .data_read_valid(ip_mem_data_read_valid), .data_write(ip_mem_data_write),
   .comm_cmd(ip_comm_cmd), .comm_data_in(ip_comm_data_in), .comm_data_in_valid(ip_comm_data_in_valid), .comm_data_out(ip_comm_data_out), .comm_data_out_valid(ip_comm_data_out_valid),
   .comm_data_out_free(ip_comm_data_out_free)
);

ram_interface ram_interface(.clk(clk), .addr(ip_mem_addr), .wr_en(ip_mem_wr_en), .rd_en(ip_mem_rd_en),
   .data_write(ip_mem_data_write), .data_read(ip_mem_data_read), .data_read_valid(ip_mem_data_read_valid)
);

spi_interface spi_interface(.clk(clk), .spi_sck(SPI_SCK), .spi_ss(SPI_SS), .spi_mosi(SPI_MOSI), .spi_miso(SPI_MISO),
   .spi_cmd(ip_comm_cmd), .spi_data_out(ip_comm_data_in), .spi_data_out_valid(ip_comm_data_in_valid), .spi_data_in(ip_comm_data_out), .spi_data_in_valid(ip_comm_data_out_valid),
   .spi_data_in_free(ip_comm_data_out_free), .led_debug(spi_led_debug)
);

initial begin
   led <= 3'b000;
end

always @(posedge clk)
begin
   led <= spi_led_debug;
end

endmodule

#ifndef SPI_LIB_H
#define SPI_LIB_H
#include <ftdi.h>

// ftdi initialization taken from iceprog https://github.com/cliffordwolf/icestorm/blob/master/iceprog/iceprog.c
// ---------------------------------------------------------
// MPSSE / FTDI definitions
// ---------------------------------------------------------

/* FTDI bank pinout typically used for iCE dev boards
 * BUS IO | Signal | Control
 * -------+--------+--------------
 * xDBUS0 |    SCK | MPSSE
 * xDBUS1 |   MOSI | MPSSE
 * xDBUS2 |   MISO | MPSSE
 * xDBUS3 |     nc |
 * xDBUS4 |     CS | GPIO
 * xDBUS5 |     nc |
 * xDBUS6 |  CDONE | GPIO
 * xDBUS7 | CRESET | GPIO
 */

 /* MPSSE engine command definitions */
 enum mpsse_cmd
 {
   /* Mode commands */
   MC_SETB_LOW = 0x80, /* Set Data bits LowByte */
   MC_READB_LOW = 0x81, /* Read Data bits LowByte */
   MC_SETB_HIGH = 0x82, /* Set Data bits HighByte */
   MC_READB_HIGH = 0x83, /* Read data bits HighByte */
   MC_LOOPBACK_EN = 0x84, /* Enable loopback */
   MC_LOOPBACK_DIS = 0x85, /* Disable loopback */
   MC_SET_CLK_DIV = 0x86, /* Set clock divisor */
   MC_FLUSH = 0x87, /* Flush buffer fifos to the PC. */
   MC_WAIT_H = 0x88, /* Wait on GPIOL1 to go high. */
   MC_WAIT_L = 0x89, /* Wait on GPIOL1 to go low. */
   MC_TCK_X5 = 0x8A, /* Disable /5 div, enables 60MHz master clock */
   MC_TCK_D5 = 0x8B, /* Enable /5 div, backward compat to FT2232D */
   MC_EN_3PH_CLK = 0x8C, /* Enable 3 phase clk, DDR I2C */
   MC_DIS_3PH_CLK = 0x8D, /* Disable 3 phase clk */
   MC_CLK_N = 0x8E, /* Clock every bit, used for JTAG */
   MC_CLK_N8 = 0x8F, /* Clock every byte, used for JTAG */
   MC_CLK_TO_H = 0x94, /* Clock until GPIOL1 goes high */
   MC_CLK_TO_L = 0x95, /* Clock until GPIOL1 goes low */
   MC_EN_ADPT_CLK = 0x96, /* Enable adaptive clocking */
   MC_DIS_ADPT_CLK = 0x97, /* Disable adaptive clocking */
   MC_CLK8_TO_H = 0x9C, /* Clock until GPIOL1 goes high, count bytes */
   MC_CLK8_TO_L = 0x9D, /* Clock until GPIOL1 goes low, count bytes */
   MC_TRI = 0x9E, /* Set IO to only drive on 0 and tristate on 1 */
   /* CPU mode commands */
   MC_CPU_RS = 0x90, /* CPUMode read short address */
   MC_CPU_RE = 0x91, /* CPUMode read extended address */
   MC_CPU_WS = 0x92, /* CPUMode write short address */
   MC_CPU_WE = 0x93, /* CPUMode write extended address */
 };

#define MC_DATA_TMS  (0x40) /* When set use TMS mode */
#define MC_DATA_IN   (0x20) /* When set read data (Data IN) */
#define MC_DATA_OUT  (0x10) /* When set write data (Data OUT) */
#define MC_DATA_LSB  (0x08) /* When set input/output data LSB first. */
#define MC_DATA_ICN  (0x04) /* When set receive data on negative clock edge */
#define MC_DATA_BITS (0x02) /* When set count bits not bytes */
#define MC_DATA_OCN  (0x01) /* When set update data on negative clock edge */

#define STATUS_FPGA_RECV_OFFSET 6 //fpga has received data
#define STATUS_FPGA_SEND_OFFSET 7 //fpga has sent data

#define STATUS_FPGA_RECV_MASK (0x1<<STATUS_FPGA_RECV_OFFSET)
#define STATUS_FPGA_SEND_MASK (0x1<<STATUS_FPGA_SEND_OFFSET)

//init spi comm, returns 0 if there is no problem
int spi_init();

//send without caring about result
int spi_command_send(uint8_t cmd, uint8_t param[3]);

//sends one byte without caring about result
int spi_command_send(uint8_t cmd, uint8_t param);

int spi_command_send_32B(uint8_t cmd, uint8_t data[32]);

//send 32 bits
int spi_command_send_32(uint8_t cmd, uint32_t val32b);

//sends data and receive answer
int spi_command_send_recv(uint8_t cmd, uint8_t send_param[3], uint8_t recv_data[2]);

int spi_command_send_recv_32B(uint8_t cmd, uint8_t send_param[32], uint8_t recv_data[31]);

#endif

